208	import { useState } from 'react';
209	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
210	import { getJson, postJson } from '../../api/http';
211	
212	// A project's budget summary as the server returns it: the budget set on it, how much has been
213	// invoiced against it (the sum of its invoices), and what is left (budget minus invoiced).
214	type Budget = {
215	  budget: number;
216	  invoiced: number;
217	  remaining: number;
218	};
219	
220	// Money rendered with thousands separators, like $1,000.00 — the budget/invoiced/remaining figures
221	// can run large, so they read with grouping (the test contract for this panel).
222	const dollars = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
223	
224	// A project's budget, rendered in the project-detail context: what is planned, what has been
225	// invoiced against it, and what is left — plus a form to set the budget. Server data is read with
226	// useQuery under a key that starts with ['invoices'] (the invoiced figure aggregates the project's
227	// invoices, like the client statement does), so an invoice write that invalidates ['invoices']
228	// refreshes this too — never copied into state, never hand-maintained (rule 5). Setting the budget
229	// is a useMutation that invalidates ['invoices'] so the panel refetches with the new figures. The
230	// only useState is the amount the user is currently typing (rule 4).
231	export function ProjectBudgetPanel({ projectId }: { projectId: number }) {
232	  const queryClient = useQueryClient();
233	  const query = useQuery({
234	    queryKey: ['invoices', 'projectBudget', projectId],
235	    queryFn: () => getJson<Budget>(`/api/projects/budget?projectId=${projectId}`),
236	  });
237	
238	  const [budget, setBudget] = useState('');
239	  const [error, setError] = useState('');
240	
241	  const save = useMutation({
242	    mutationFn: () =>
243	      postJson<Budget>('/api/projects/budget', { projectId, budget: Number(budget) }),
244	    onSuccess: () => {
245	      setBudget('');
246	      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
247	    },
248	  });
249	
250	  const data = query.data;
251	
252	  return (
253	    <section data-testid="project-budget-panel">
254	      <form
255	        data-testid="project-budget-form"
256	        onSubmit={(e) => {
257	          e.preventDefault();
258	          const value = Number(budget);
259	          if (!budget.trim() || Number.isNaN(value) || value < 0) {
260	            setError('Budget must be zero or more.');
261	            return;
262	          }
263	          setError('');
264	          save.mutate();
265	        }}
266	      >
267	        <input
268	          data-testid="project-budget-input"
269	          type="number"
270	          step="0.01"
271	          placeholder="Budget"
272	          value={budget}
273	          onChange={(e) => {
274	            setBudget(e.target.value);
275	            setError('');
276	          }}
277	        />
278	        <button data-testid="project-budget-submit" type="submit">
279	          Set budget
280	        </button>
281	        {error && (
282	          <p data-testid="project-budget-error" role="alert">
283	            {error}
284	          </p>
285	        )}
286	      </form>
287	
288	      <dl>
289	        <dt>Budget</dt>
290	        <dd data-testid="project-budget">{data ? dollars.format(Number(data.budget)) : ''}</dd>
291	        <dt>Invoiced</dt>
292	        <dd data-testid="project-invoiced">
293	          {data ? dollars.format(Number(data.invoiced)) : ''}
294	        </dd>
295	        <dt>Remaining</dt>
296	        <dd data-testid="project-remaining">
297	          {data ? dollars.format(Number(data.remaining)) : ''}
298	        </dd>
299	      </dl>
300	    </section>
301	  );
302	}
