393	// A project as the server returns it: it carries the client's NAME so the list shows the name, not
394	// the id. project.clientId is the id the form's select submits. `archived` projects are kept but
395	// hidden from the default list.
396	// A project's state: ACTIVE while worked on, ON_HOLD when paused, FINISHED when done. Stored on the
397	// row and pickable when creating a project (V21__project_status.sql).
398	export const PROJECT_STATUSES = ['ACTIVE', 'ON_HOLD', 'FINISHED'] as const;
399	export type ProjectStatus = (typeof PROJECT_STATUSES)[number];
400	
401	export type Project = {
402	  id: number;
403	  name: string;
404	  clientId: number;
405	  clientName: string;
406	  archived: boolean;
407	  status: ProjectStatus;
