410	// The projects page: the whole list of projects plus the form to add one and pick its client.
411	// Server data is read with useQuery (['projects'] for the list, ['clients'] — the SAME key the
412	// clients feature owns — for the select options) and changed with useMutation + invalidateQueries.
413	// The only useState here is the fields the user is currently filling in (rule 4).
414	export function ProjectsPage() {
415	  const queryClient = useQueryClient();
416	  const projects = useQuery({
417	    queryKey: ['projects'],
418	    queryFn: () => getJson<Project[]>('/api/projects'),
