425	  // Whether archived projects are revealed lives in the URL, owned by
426	  // features/projects/showArchived.slot.tsx. The page reads the same key: by default archived
427	  // projects drop off the list; the toggle brings them back — no server data copied into state.
428	  const [showArchived] = useSearchParam('showArchived', asFlag);
429	
430	  // Which tag the list is filtered to lives in the URL, owned by features/projects/tagFilter.slot.tsx.
431	  // The page reads the same key and narrows its rows to projects carrying that tag; the pairings come
432	  // from useQuery under ['projectTags'] — the SAME key the tags panel owns (rule 5) — so nothing is
433	  // passed between the control and the list. Undefined means no filter: every project shows.
434	  const [tagFilter] = useSearchParam('projectTag', asNumber);
435	
436	  // Which status the list is filtered to lives in the URL, owned by
437	  // features/projects/statusFilter.slot.tsx. The page reads the same key and narrows its rows to
438	  // projects at that status; empty means no filter, so every project shows.
439	  const [statusFilter] = useSearchParam('projectStatus', asString);
440	  const projectTags = useQuery({
441	    queryKey: ['projectTags'],
442	    queryFn: () => getJson<ProjectTag[]>('/api/project-tags'),
443	  });
444	
445	  const [name, setName] = useState('');
446	  const [clientId, setClientId] = useState('');
447	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
448	
449	  const create = useMutation({
