451	      postJson<Project>('/api/projects', { name, clientId: Number(clientId), status }),
452	    onSuccess: () => {
453	      setName('');
454	      setClientId('');
455	      setStatus('ACTIVE');
456	      void queryClient.invalidateQueries({ queryKey: ['projects'] });
457	    },
458	  });
459	
460	  const taggedIds = new Set(
461	    (projectTags.data ?? [])
462	      .filter((pt) => pt.tagId === tagFilter)
463	      .map((pt) => pt.projectId),
464	  );
465	  const rows = (projects.data ?? [])
466	    .filter((p) => showArchived || !p.archived)
467	    .filter((p) => tagFilter === undefined || taggedIds.has(p.id))
468	    .filter((p) => statusFilter === '' || p.status === statusFilter);
469	  const clientOptions = clients.data ?? [];
470	
471	  return (
472	    <section data-testid="projects">
473	      <form
474	        data-testid="project-form"
