568	// A project's tags, rendered in the project-detail context: the chips already on this project, a
569	// per-chip remove button, and a select of the remaining tags to add one. Both lists come from
570	// useQuery — every tag under ['tags'], every pairing under ['projectTags'] — and are filtered to
571	// this project here (rule 5); nothing is copied into state or hand-maintained. Adding and removing
572	// are useMutations that invalidate ['projectTags'], so the chips refetch themselves. The only
573	// useState is the tag the user has currently picked but not yet added (rule 4).
574	export function ProjectTagsPanel({ projectId }: { projectId: number }) {
575	  const queryClient = useQueryClient();
576	  const tags = useQuery({
577	    queryKey: ['tags'],
578	    queryFn: () => getJson<Tag[]>('/api/tags'),
