589	      postJson<ProjectTag>('/api/project-tags', { projectId, tagId }),
590	    onSuccess: () => {
591	      setSelected('');
592	      void queryClient.invalidateQueries({ queryKey: ['projectTags'] });
593	    },
594	  });
595	
596	  const remove = useMutation({
597	    mutationFn: (tagId: number) =>
598	      postJson<ProjectTag>('/api/project-tags/remove', { projectId, tagId }),
599	    onSuccess: () => {
600	      void queryClient.invalidateQueries({ queryKey: ['projectTags'] });
601	    },
602	  });
603	
604	  const assigned = (projectTags.data ?? []).filter((pt) => pt.projectId === projectId);
605	  const assignedIds = new Set(assigned.map((pt) => pt.tagId));
606	  const available = (tags.data ?? []).filter((t) => !assignedIds.has(t.id));
