683	// ['tasks'] key and filtered to the project this panel is handed — never copied into state, never
684	// hand-maintained (rule 5). Adding and toggling are useMutations that invalidate ['tasks'], so the
685	// list refetches itself. The only useState here is the title the user is currently typing (rule 4).
686	export function ProjectTasksPanel({ projectId }: { projectId: number }) {
687	  const queryClient = useQueryClient();
688	  const tasks = useQuery({
689	    queryKey: ['tasks'],
690	    queryFn: () => getJson<Task[]>('/api/tasks'),
691	  });
692	
693	  const [title, setTitle] = useState('');
694	
695	  const create = useMutation({
696	    mutationFn: () => postJson<Task>('/api/tasks', { projectId, title }),
697	    onSuccess: () => {
698	      setTitle('');
699	      void queryClient.invalidateQueries({ queryKey: ['tasks'] });
700	    },
701	  });
702	
703	  const toggle = useMutation({
704	    mutationFn: (id: number) => postJson<Task>('/api/tasks/toggle', { id }),
705	    onSuccess: () => {
706	      void queryClient.invalidateQueries({ queryKey: ['tasks'] });
707	    },
708	  });
709	
710	  // The open/done filter lives in the URL under the `taskFilter` key, owned by taskFilter.slot.tsx.
711	  // We read the same key here (rule 4) and narrow the rows: OPEN keeps done=false, DONE keeps
712	  // done=true, and no value (or an unknown one) shows every task.
713	  const [filter] = useSearchParam('taskFilter', asString);
714	  const rows = (tasks.data ?? [])
715	    .filter((t) => t.projectId === projectId)
716	    .filter((t) => (filter === 'OPEN' ? !t.done : filter === 'DONE' ? t.done : true));
717	
718	  return (
719	    <section data-testid="project-tasks">
720	      <form
721	        data-testid="task-form"
722	        onSubmit={(e) => {
723	          e.preventDefault();
724	          if (!title.trim()) {
725	            return;
726	          }
727	          create.mutate();
728	        }}
729	      >
730	        <input
731	          data-testid="task-form-title"
732	          placeholder="Task title"
733	          value={title}
734	          onChange={(e) => setTitle(e.target.value)}
735	        />
736	        <button data-testid="task-form-submit" type="submit">
737	          Add task
738	        </button>
739	      </form>
740	
741	      {rows.length === 0 ? (
742	        <p data-testid="project-tasks-empty">No tasks yet.</p>
743	      ) : (
744	        <table data-testid="project-tasks-table">
745	          <thead>
746	            <tr>
747	              <th>Task</th>
748	              <th>Status</th>
749	              <th />
750	            </tr>
751	          </thead>
752	          <tbody>
753	            {rows.map((t) => (
754	              <tr key={t.id} data-testid={`task-row-${t.id}`}>
755	                <td data-testid="task-title">{t.title}</td>
756	                <td data-testid="task-status">{t.done ? 'DONE' : 'OPEN'}</td>
757	                <td>
758	                  <button
759	                    type="button"
760	                    data-testid={`task-toggle-${t.id}`}
761	                    onClick={() => toggle.mutate(t.id)}
762	                  >
763	                    {t.done ? 'Reopen' : 'Tick off'}
764	                  </button>
765	                </td>
766	              </tr>
767	            ))}
768	          </tbody>
769	        </table>
770	      )}
771	    </section>
772	  );
773	}
