import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { asFlag, asNumber, asString, useSearchParam } from '../../url/useSearchParam';
import type { Client } from '../clients/ClientsPage';
import type { ProjectTag } from './ProjectTagsPanel';
import { ProjectRowActions } from '../../slots/defs/projectRowActions';
import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';

// A project as the server returns it: it carries the client's NAME so the list shows the name, not
// the id. project.clientId is the id the form's select submits. `archived` projects are kept but
// hidden from the default list.
// A project's state: ACTIVE while worked on, ON_HOLD when paused, FINISHED when done. Stored on the
// row and pickable when creating a project (V21__project_status.sql).
export const PROJECT_STATUSES = ['ACTIVE', 'ON_HOLD', 'FINISHED'] as const;
export type ProjectStatus = (typeof PROJECT_STATUSES)[number];

export type Project = {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
};

// The projects page: the whole list of projects plus the form to add one and pick its client.
// Server data is read with useQuery (['projects'] for the list, ['clients'] — the SAME key the
// clients feature owns — for the select options) and changed with useMutation + invalidateQueries.
// The only useState here is the fields the user is currently filling in (rule 4).
export function ProjectsPage() {
  const queryClient = useQueryClient();
  const projects = useQuery({
    queryKey: ['projects'],
    queryFn: () => getJson<Project[]>('/api/projects'),
  });
  const clients = useQuery({
    queryKey: ['clients'],
    queryFn: () => getJson<Client[]>('/api/clients'),
  });

  // Whether archived projects are revealed lives in the URL, owned by
  // features/projects/showArchived.slot.tsx. The page reads the same key: by default archived
  // projects drop off the list; the toggle brings them back — no server data copied into state.
  const [showArchived] = useSearchParam('showArchived', asFlag);

  // Which tag the list is filtered to lives in the URL, owned by features/projects/tagFilter.slot.tsx.
  // The page reads the same key and narrows its rows to projects carrying that tag; the pairings come
  // from useQuery under ['projectTags'] — the SAME key the tags panel owns (rule 5) — so nothing is
  // passed between the control and the list. Undefined means no filter: every project shows.
  const [tagFilter] = useSearchParam('projectTag', asNumber);

  // Which status the list is filtered to lives in the URL, owned by
  // features/projects/statusFilter.slot.tsx. The page reads the same key and narrows its rows to
  // projects at that status; empty means no filter, so every project shows.
  const [statusFilter] = useSearchParam('projectStatus', asString);
  const projectTags = useQuery({
    queryKey: ['projectTags'],
    queryFn: () => getJson<ProjectTag[]>('/api/project-tags'),
  });

  const [name, setName] = useState('');
  const [clientId, setClientId] = useState('');
  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');

  const create = useMutation({
    mutationFn: () =>
      postJson<Project>('/api/projects', { name, clientId: Number(clientId), status }),
    onSuccess: () => {
      setName('');
      setClientId('');
      setStatus('ACTIVE');
      void queryClient.invalidateQueries({ queryKey: ['projects'] });
    },
  });

  const taggedIds = new Set(
    (projectTags.data ?? [])
      .filter((pt) => pt.tagId === tagFilter)
      .map((pt) => pt.projectId),
  );
  const rows = (projects.data ?? [])
    .filter((p) => showArchived || !p.archived)
    .filter((p) => tagFilter === undefined || taggedIds.has(p.id))
    .filter((p) => statusFilter === '' || p.status === statusFilter);
  const clientOptions = clients.data ?? [];

  return (
    <section data-testid="projects">
      <form
        data-testid="project-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!name.trim() || !clientId) {
            return;
          }
          create.mutate();
        }}
      >
        <input
          data-testid="project-form-name"
          placeholder="Job name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <select
          data-testid="project-form-client"
          value={clientId}
          onChange={(e) => setClientId(e.target.value)}
        >
          <option value="">Select a client</option>
          {clientOptions.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
        <select
          data-testid="project-form-status"
          value={status}
          onChange={(e) => setStatus(e.target.value as ProjectStatus)}
        >
          {PROJECT_STATUSES.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>
        <button data-testid="project-form-submit" type="submit">
          Add job
        </button>
      </form>

      <div data-testid="projects-toolbar">
        <ProjectsToolbar.Slot />
      </div>

      {rows.length === 0 ? (
        <p data-testid="projects-empty">No projects yet.</p>
      ) : (
        <table data-testid="projects-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Client</th>
              <th>Status</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {rows.map((p) => (
              <tr key={p.id} data-testid={`project-row-${p.id}`}>
                <td data-testid="project-name">{p.name}</td>
                <td data-testid="project-client">{p.clientName}</td>
                <td data-testid="project-status">{p.status}</td>
                <td>
                  <ProjectRowActions.Slot projectId={p.id} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';
import type { Project } from './ProjectsPage';

// A client's projects: the projects listing scoped to one client, rendered in the client-detail
// context. Server data is read with useQuery under the SAME ['projects'] key the projects page owns
// (so a project write that invalidates ['projects'] refreshes this too) and filtered to the client
// it is handed — never copied into state, never hand-maintained (rule 5). Reuses the
// project-row-<id>/project-name anchors inside its own client-projects-table.
export function ClientProjectsPanel({ clientId }: { clientId: number }) {
  const projects = useQuery({
    queryKey: ['projects'],
    queryFn: () => getJson<Project[]>('/api/projects'),
  });

  // Whether the finished and hidden (archived) projects are revealed lives in the URL, owned by
  // features/projects/clientProjectsShowAll.slot.tsx. This panel reads the same key: by default it
  // shows only the client's live work (ACTIVE and not archived); flip the key and every project
  // for the client shows. Nothing is passed between the toggle and the panel (rule 4).
  const [showAll] = useSearchParam('clientProjectsShowAll', asFlag);

  const rows = (projects.data ?? []).filter(
    (p) => p.clientId === clientId && (showAll || (p.status === 'ACTIVE' && !p.archived)),
  );

  return (
    <section data-testid="client-projects">
      {rows.length === 0 ? (
        <p data-testid="client-projects-empty">No projects yet.</p>
      ) : (
        <table data-testid="client-projects-table">
          <thead>
            <tr>
              <th>Name</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((p) => (
              <tr key={p.id} data-testid={`project-row-${p.id}`}>
                <td data-testid="project-name">{p.name}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

import { ClientDetail } from '../../slots/defs/clientDetail';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

// The show-all toggle for a client's projects — its own file, filling the client-detail slot above
// the projects panel (order 5, before the panel at 10). It OWNS the `clientProjectsShowAll` URL key
// (rule 4: a show/hide toggle outlives a click, so it lives in the URL, not useState). The projects
// panel reads the same key to decide whether the finished and archived projects are listed; nothing
// is passed between them. Carries data-testid="client-projects-show-all" (the test contract).
function ClientProjectsShowAll() {
  const [showAll, setShowAll] = useSearchParam('clientProjectsShowAll', asFlag);
  return (
    <button
      type="button"
      data-testid="client-projects-show-all"
      aria-pressed={showAll}
      onClick={() => setShowAll(showAll ? undefined : true)}
    >
      {showAll ? 'Show active only' : 'Show all projects'}
    </button>
  );
}

export const contribution = ClientDetail.fill({ order: 5, Component: ClientProjectsShowAll });

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { money } from '../../ui/money';

// The whole-app summary the server returns: how many clients and projects exist, and the money
// still owed (the sum of every SENT invoice's amount — drafts and paid invoices are excluded).
export type DashboardSummary = {
  clientsCount: number;
  projectsCount: number;
  outstandingTotal: number;
  overdueCount: number;
};

// The home screen: a read-only dashboard of the counts and the outstanding total. Server data is
// read with useQuery under the ['dashboard'] key — never copied into state. A write elsewhere that
// invalidates ['clients'], ['projects'] or ['invoices'] does not touch this key, so the dashboard
// simply refetches on its own next mount; it stays a single source of truth for the summary.
export function Dashboard() {
  const summary = useQuery({
    queryKey: ['dashboard'],
    queryFn: () => getJson<DashboardSummary>('/api/dashboard'),
  });

  const data = summary.data;

  return (
    <section data-testid="dashboard">
      <dl>
        <dt>Clients</dt>
        <dd data-testid="dashboard-clients-count">{data?.clientsCount ?? 0}</dd>
        <dt>Projects</dt>
        <dd data-testid="dashboard-projects-count">{data?.projectsCount ?? 0}</dd>
        <dt>Outstanding</dt>
        <dd data-testid="dashboard-outstanding-total">
          {money(Number(data?.outstandingTotal ?? 0))}
        </dd>
        <dt>Overdue invoices</dt>
        <dd data-testid="dashboard-overdue-count">{data?.overdueCount ?? 0}</dd>
      </dl>
    </section>
  );
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import type { Client } from '../clients/ClientsPage';
import type { Project } from '../projects/ProjectsPage';

// One search box across both clients and projects. The server does the matching (GET /api/search)
// and hands back the two groups; this component just renders them, grouped by kind.
type SearchResults = { clients: Client[]; projects: Project[] };

// The global search box and its results. It OWNS the `search` URL key (rule 4: a search term
// outlives a click, so it lives in the URL, not useState). The results are read with useQuery under
// ['search', term] — server data, never copied into state (rule 5) — and only fetched once there is
// something to look for. Carries data-testid="global-search" (the test contract), with the matches
// grouped under data-testid="search-clients" and data-testid="search-projects".
export function GlobalSearch() {
  const [q, setQ] = useSearchParam('search', asString);
  const term = q.trim();
  const results = useQuery({
    queryKey: ['search', term],
    queryFn: () => getJson<SearchResults>(`/api/search?q=${encodeURIComponent(term)}`),
    enabled: term.length > 0,
  });

  const clients = results.data?.clients ?? [];
  const projects = results.data?.projects ?? [];

  return (
    <div data-testid="global-search-panel">
      <input
        data-testid="global-search"
        type="search"
        placeholder="Search clients and projects"
        value={q}
        onChange={(e) => setQ(e.target.value)}
      />
      {term.length > 0 && (
        <div data-testid="search-results">
          <section data-testid="search-clients">
            {clients.map((c) => (
              <div key={c.id} data-testid={`client-row-${c.id}`}>
                <span data-testid="client-name">{c.name}</span>
                <span data-testid="client-email">{c.email}</span>
              </div>
            ))}
          </section>
          <section data-testid="search-projects">
            {projects.map((p) => (
              <div key={p.id} data-testid={`project-row-${p.id}`}>
                <span data-testid="project-name">{p.name}</span>
                <span data-testid="project-client">{p.clientName}</span>
              </div>
            ))}
          </section>
        </div>
      )}
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, asString, useSearchParam } from '../../url/useSearchParam';
import { AllInvoicesToolbar } from '../../slots/defs/allInvoicesToolbar';
import { money } from '../../ui/money';

// An invoice as the all-invoices endpoint returns it: which project it is for (by NAME, joined
// server-side), its amount, and its lifecycle status (the stage it is at). See InvoicesAllGet.
export type InvoiceView = {
  id: number;
  projectId: number;
  projectName: string;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};

// One place listing every invoice across all projects, each row showing the project it is for and
// the stage it is at. Server data is read with useQuery under ['invoices', 'all'] — the key still
// starts with 'invoices', so a write that invalidates ['invoices'] refreshes this list too (rule 5).
export function AllInvoicesPage() {
  // The chosen stage lives in the URL (owned by features/invoices/statusFilter.slot.tsx). The page
  // reads the same key and asks the server for the narrowed list — a single source of truth, no
  // server data copied into state or filtered by hand. The key still starts with 'invoices', so a
  // write that invalidates ['invoices'] refreshes this list too (rule 5).
  const [status] = useSearchParam('invoiceStatus', asString);
  // The huge list is shown a page at a time. The chosen page lives in the URL too (owned by
  // features/invoices/pagination.slot.tsx, which renders the next/previous controls); the page reads
  // the same key and asks the server for just that slice — the same single-source-of-truth shape as
  // the status filter above, no rows sliced or held in state here.
  const [page] = useSearchParam('invoicePage', asNumber);
  const currentPage = page ?? 1;
  const invoices = useQuery({
    queryKey: ['invoices', 'all', status, currentPage],
    queryFn: () => {
      const params = new URLSearchParams({ page: String(currentPage) });
      if (status) params.set('status', status);
      return getJson<InvoiceView[]>(`/api/invoices/all?${params.toString()}`);
    },
  });

  const rows = invoices.data ?? [];

  return (
    <section data-testid="all-invoices">
      <div data-testid="all-invoices-toolbar">
        <AllInvoicesToolbar.Slot />
      </div>
      {rows.length === 0 ? (
        <p data-testid="all-invoices-empty">No invoices yet.</p>
      ) : (
        <table data-testid="all-invoices-table">
          <thead>
            <tr>
              <th>Project</th>
              <th>Amount</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((i) => (
              <tr key={i.id} data-testid={`invoice-row-${i.id}`}>
                <td data-testid="invoice-project">{i.projectName}</td>
                <td data-testid="invoice-amount">{money(Number(i.amount))}</td>
                <td data-testid="invoice-status">{i.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { ClientDetail } from '../../slots/defs/clientDetail';
import type { Project } from '../projects/ProjectsPage';
import type { Contact } from '../contacts/ClientContactsPanel';

// At-a-glance counts of a client's projects and contacts — its own file, filling the client-detail
// slot above the panels (order 5, before projects at 10). It owns no data of its own: it reads the
// SAME ['projects'] and ['contacts'] keys the sibling panels own, scoped to the client it is handed,
// so a project or contact write that invalidates either key refreshes these counts too (rule 5).
// The counts are derived, never copied into state.
export function ClientCounts({ clientId }: { clientId: number }) {
  const projects = useQuery({
    queryKey: ['projects'],
    queryFn: () => getJson<Project[]>('/api/projects'),
  });
  const contacts = useQuery({
    queryKey: ['contacts'],
    queryFn: () => getJson<Contact[]>('/api/contacts'),
  });

  const projectCount = (projects.data ?? []).filter((p) => p.clientId === clientId).length;
  const contactCount = (contacts.data ?? []).filter((c) => c.clientId === clientId).length;

  return (
    <dl data-testid="client-counts">
      <div>
        <dt>Projects</dt>
        <dd data-testid="client-projects-count">{projectCount}</dd>
      </div>
      <div>
        <dt>Contacts</dt>
        <dd data-testid="client-contacts-count">{contactCount}</dd>
      </div>
    </dl>
  );
}

export const contribution = ClientDetail.fill({
  order: 5,
  Component: ClientCounts,
});

